# Native-R regression corpus against the read-only pinned SpecQR Python core.
# No Python, Node, codec, network, or optional R package is used by these tests.
if (!exists("segment", mode = "function")) {
  root <- if (dir.exists("R")) "." else if (dir.exists("../R")) ".." else "specqr-r-work/SpecQR-R"
  for (file in sort(list.files(file.path(root, "R"), pattern = "^0[0-4]-.*[.]R$", full.names = TRUE))) source(file)
}
.core_checks <- 0L
.check <- function(ok) { .core_checks <<- .core_checks + 1L; if (!isTRUE(ok)) stop("Core check failed at ", .core_checks) }
.expect_error <- function(expr, code = "INVALID_INPUT") {
  error <- tryCatch({ force(expr); NULL }, error = identity)
  if (!(inherits(error, "specqr_error") && identical(error$code, code)))
    stop("Expected ", code, " for ", paste(deparse(substitute(expr)), collapse = " "),
         "; got ", if (is.null(error)) "no error" else conditionMessage(error))
  .check(TRUE)
}
.md5 <- function(bytes) {
  path <- tempfile("specqr-core-"); on.exit(unlink(path)); writeBin(as.raw(bytes), path)
  unname(tools::md5sum(path))
}
.matrix_md5 <- function(x) .md5(as.raw(as.integer(t(x)) + 48L))
