independent_gf <- function(a, b) {
  product <- 0L
  for (shift in 0L:7L) if (bitwAnd(bitwShiftR(b, shift), 1L)) product <- bitwXor(product, bitwShiftL(a, shift))
  for (shift in 14L:8L) if (bitwAnd(bitwShiftR(product, shift), 1L)) product <- bitwXor(product, bitwShiftL(0x11dL, shift - 8L))
  product
}
for (a in 0L:255L) for (b in 0L:255L) .check(gf_multiply(a, b) == independent_gf(a, b))
.check(gf_multiply(0x53L, 0xcaL) == 0x8fL)
rs_data <- as.raw(((0L:256L) * 93L + 11L) %% 256L)
for (degree in 1L:255L) {
  divisor <- reed_solomon_divisor(degree); parity <- reed_solomon_remainder(rs_data, degree)
  .check(.md5(divisor) == .RS_EXPECTED[[degree]][1L]); .check(.md5(parity) == .RS_EXPECTED[[degree]][2L])
  .check(identical(reed_solomon_remainder(c(rs_data, parity), degree), raw(degree)))
  .check(identical(reed_solomon_remainder(raw(), degree), raw(degree)))
}
