.check(identical(alignment_positions(2L), c(6L, 18L)))
.check(identical(alignment_positions(32L), c(6L, 34L, 60L, 86L, 112L, 138L)))
.check(identical(alignment_positions(40L), c(6L, 30L, 58L, 86L, 114L, 142L, 170L)))
.check(identical(vapply(c("L", "M", "Q", "H"), function(level) data_codeword_count(1L, level), integer(1L), USE.NAMES = FALSE), c(19L, 16L, 13L, 9L)))
for (reference in .CORE_EXPECTED) {
  version <- reference[[1L]]; level <- reference[[2L]]; li <- match(level, c("L", "M", "Q", "H")) - 1L
  data <- as.raw(((seq_len(data_codeword_count(version, level)) - 1L) * 149L + version * 7L + li * 31L) %% 256L)
  encoded <- interleave_codewords(data, version, level)
  .check(.md5(encoded$codewords) == reference[[3L]])
  .check(encoded$data_codewords == length(data)); .check(encoded$total_codewords == raw_codeword_count(version))
  .check(encoded$error_correction_codewords + encoded$data_codewords == encoded$total_codewords)
  .check(identical(do.call(c, lapply(encoded$blocks, `[[`, "data")), data))
  for (block in encoded$blocks) .check(identical(reed_solomon_remainder(c(block$data, block$ecc), length(block$ecc)), raw(length(block$ecc))))
  for (mask in 0L:7L) {
    built <- build_matrix(encoded$codewords, version, level, mask)
    .check(is.logical(built$matrix) && identical(dim(built$matrix), rep(qr_size(version), 2L)))
    .check(.matrix_md5(built$matrix) == reference[[4L]][mask + 1L]); .check(built$penalty == reference[[5L]][mask + 1L])
    .check(penalty_score(built$matrix) == built$penalty); .check(built$mask_pattern == mask && length(built$mask_penalties) == 1L)
    .check(built$matrix[qr_size(version) - 7L, 9L])
  }
  auto <- build_matrix(encoded$codewords, version, level); best <- which.min(reference[[5L]])
  .check(auto$mask_pattern == best - 1L && auto$penalty == reference[[5L]][best])
  .check(.matrix_md5(auto$matrix) == reference[[4L]][best])
  .check(identical(vapply(auto$mask_penalties, `[[`, integer(1L), "penalty"), reference[[5L]]))
  if (version %% 10L == 0L && level == "H") cat("Core reference versions through", version, "passed\n")
}
for (reference in .SEGMENT_EXPECTED) {
