# Stored R language objects must stay data, never become evaluation instructions.
.language_ran <- FALSE
.language_value <- quote({ .language_ran <<- TRUE; "HELLO" })
for (.language_payload in list(.language_value, as.name(".language_ran"), expression(.language_ran <<- TRUE))) {
  .expect_error(normalize_segments(list(list(mode = "byte", data = .language_payload))))
  .check(identical(.language_ran, FALSE))
  .mutated_segment <- byte_segment("x"); .mutated_segment$data <- .language_payload
  .expect_error(normalize_segments(list(.mutated_segment)))
  .expect_error(bits(.mutated_segment, 1L)); .check(identical(.language_ran, FALSE))
}
.expect_error(normalize_segments(list(list(mode = .language_value, data = "x"))), "INVALID_MODE")
.check(identical(.language_ran, FALSE))

